package review

import (
	"context"
	"strings"

	"github.com/anthropics/anthropic-sdk-go"
	"github.com/anthropics/anthropic-sdk-go/option"
)

// APIs. Which wire the one call goes over. The prompt, the output schema,
// the ceiling and the cost tripwire are decided before this choice is
// consulted, so a review is the same review whichever wire carries it.
const (
	APIAnthropic = "anthropic"
	APIOpenAI    = "openai"
)

// completion is what one backend returns from one turn, in terms Run reads
// without knowing which API produced them.
type completion struct {
	text       string
	stopReason string
	// usage is filled on every path, including the ones that fail, because
	// the input is billed as soon as the request is accepted.
	usage Usage
	// refused is set when the model declined the request. detail says why,
	// when the API said.
	refused bool
	detail  string
	// truncated is set when the response hit the output cap.
	truncated bool
}

// completeAnthropic is the Messages API call. Streamed because the input is
// large and the response may be too: a non-streaming request at this size
// risks an HTTP timeout, and a timeout after paying for 120k of input is the
// worst outcome available.
func completeAnthropic(ctx context.Context, opts Options, res *Result) (completion, error) {
	var clientOpts []option.RequestOption
	if opts.APIKey != "" {
		clientOpts = append(clientOpts, option.WithAPIKey(opts.APIKey))
	}
	if opts.BaseURL != "" {
		clientOpts = append(clientOpts, option.WithBaseURL(opts.BaseURL))
	}
	client := anthropic.NewClient(clientOpts...)

	// Still no cache breakpoint on this path, but no longer for the old
	// reason. What blocked one was the response schema: it sits in front of the
	// system block and the ruling sent a different one from the review it
	// follows, so each call wrote the shared prefix and read none of it, at
	// 171,690 and 170,601 tokens on a real run. The contract now goes as a
	// constant tool array with the stage picked by tool_choice, so the review
	// and the ruling send the same bytes ahead of the prompt and a breakpoint
	// would be read back. Marking one is the next change and is not this one;
	// until it lands a write nobody reads would still cost a quarter above
	// base input, so this call pays the base rate and no more.
	//
	// Samples are a separate case and stay uncached whatever happens here:
	// they go out together, so three concurrent calls over one fresh prefix
	// each write it and none reads. Explore mode keeps its own breakpoints,
	// where one growing conversation means a later turn really does read an
	// earlier one.
	stream := client.Messages.NewStreaming(ctx, anthropicParams(opts, res))
	// Next returning false at the end of the stream does not close the
	// response body; only Close does. One per call here, so a deferred close
	// is enough.
	defer func() { _ = stream.Close() }()
	var msg anthropic.Message
	// The message_start event carries the input count before any content
	// arrives, so a stream that breaks partway still reports what it cost.
	usage := func() Usage {
		return Usage{
			InputTokens:      msg.Usage.InputTokens,
			OutputTokens:     msg.Usage.OutputTokens,
			CacheReadTokens:  msg.Usage.CacheReadInputTokens,
			CacheWriteTokens: msg.Usage.CacheCreationInputTokens,
		}
	}
	hb := newHeartbeat(opts, res.stage())
	for stream.Next() {
		ev := stream.Current()
		if err := msg.Accumulate(ev); err != nil {
			return completion{usage: usage()}, err
		}
		hb.observe(ev.Delta.Type, ev.Delta.Text, ev.Delta.Thinking, ev.Delta.PartialJSON)
	}
	if err := stream.Err(); err != nil {
		return completion{usage: usage()}, err
	}
	c := completion{
		text:       structuredOf(msg),
		stopReason: string(msg.StopReason),
		usage:      usage(),
		truncated:  msg.StopReason == anthropic.StopReasonMaxTokens,
	}
	if msg.StopReason == anthropic.StopReasonRefusal {
		c.refused = true
		c.detail = string(msg.StopDetails.Category)
	}
	return c, nil
}

// anthropicParams is the request one review makes, without sending it.
//
// Split out so the batch path builds the identical request: a batched review
// that differed from a streamed one in any field would make the eval's cheap
// arm measure something other than what ships.
func anthropicParams(opts Options, res *Result) anthropic.MessageNewParams {
	// The shared prefix is its own block, and the breakpoint goes at the end
	// of it. On the system block instead it would cache a few thousand tokens
	// of the hundred and seventy thousand that matter; behind the stage's
	// instruction it would cache bytes the next call does not send.
	prefix := anthropic.NewTextBlock(res.Prompt)
	if opts.cacheOn() {
		prefix.OfText.CacheControl = anthropic.CacheControlEphemeralParam{
			TTL: anthropic.CacheControlEphemeralTTL(opts.CacheTTL),
		}
	}
	blocks := []anthropic.ContentBlockParamUnion{prefix}
	if res.Tail != "" {
		blocks = append(blocks, anthropic.NewTextBlock(res.Tail))
	}
	params := anthropic.MessageNewParams{
		Model:     anthropic.Model(opts.Model),
		MaxTokens: opts.MaxTokens,
		System:    []anthropic.TextBlockParam{{Text: res.System}},
		Messages:  []anthropic.MessageParam{anthropic.NewUserMessage(blocks...)},
		// The whole catalogue, every time, with the stage chosen by name. See
		// tools.go for why the contract cannot be a per-call output format.
		Tools:      anthropicTools(opts),
		ToolChoice: anthropic.ToolChoiceParamOfTool(res.stage()),
	}
	if opts.Effort != "" {
		params.OutputConfig.Effort = anthropic.OutputConfigEffort(opts.Effort)
	}
	return params
}

// structuredOf is the body the parser is handed: the arguments of the tool
// call the request forced.
//
// It falls back to the text blocks when no tool call came back. A model that
// answers a forced tool_choice in prose is a broken contract, not a review
// with no findings, and the parse below will say so with the body in front of
// it. Returning nothing here would report it as an empty response instead,
// which is the one thing this producer must not do.
func structuredOf(msg anthropic.Message) string {
	for _, block := range msg.Content {
		if t, ok := block.AsAny().(anthropic.ToolUseBlock); ok {
			return string(t.Input)
		}
	}
	return textOf(msg)
}

func textOf(msg anthropic.Message) string {
	var b strings.Builder
	for _, block := range msg.Content {
		if t, ok := block.AsAny().(anthropic.TextBlock); ok {
			b.WriteString(t.Text)
		}
	}
	return b.String()
}

package review

import (
	"bytes"
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"time"
)

// The cost target is an average, not a cap on every review.
//
// This matters for what the ceiling is for. If every review had to come in
// under the target, the ceiling would be a governor and it would trim context
// from exactly the large changes that most need it. Because the target is an
// average, a large change is allowed to cost more than a small one, and the
// ceiling's job is only to stop the pathological tail.
//
// An average is a claim about a distribution, and a distribution has to be
// measured. So every review appends one line here, and the numbers are read
// back rather than asserted.

// ledgerFile is where per-review cost lands, beside the report it produced.
const ledgerFile = "reviews.jsonl"

// Entry is one review's cost record.
type Entry struct {
	At       time.Time `json:"at"`
	API      string    `json:"api,omitempty"`
	Model    string    `json:"model"`
	Effort   string    `json:"effort,omitempty"`
	Usage    Usage     `json:"usage"`
	CostUSD  float64   `json:"costUSD"`
	Known    bool      `json:"costKnown"`
	Seconds  float64   `json:"seconds"`
	Findings int       `json:"findings"`
	// StopReason is what ended the last turn, and Truncated whether that was
	// the output cap. Recorded because a review that found nothing and a
	// review that was cut off mid-finding cost the same and look identical
	// here without them: the design expects roughly three changes in ten to
	// deserve no comment, so a zero-finding line is only readable as a clean
	// pass once the cap can be ruled out.
	StopReason string `json:"stopReason,omitempty"`
	Truncated  bool   `json:"truncated,omitempty"`
	// Batched marks a row billed at the Message Batches tier's half rate.
	// Summarize leaves those out of the distribution: the target is a claim
	// about what a review costs the person waiting for it, and a sweep of
	// half-price fixtures would drag that average somewhere no interactive
	// run can reach.
	Batched bool `json:"batched,omitempty"`
	// Cached marks a row that asked for a cache breakpoint. Usage already
	// carries the read and write counts; this says whether a zero read is a
	// prefix that broke or a run that never asked, which are the same two
	// numbers and opposite facts. These rows stay in the distribution: a
	// cached review is what an interactive review costs once this is on.
	Cached bool `json:"cached,omitempty"`
	// Synopsis marks a row whose walkthrough came from its own call, and
	// SynopsisOutputTokens what that call wrote. Both are needed to read the
	// row: the output median below prices a judging call, and a row that
	// split the two jobs wrote its description somewhere this number does not
	// count.
	Synopsis             bool  `json:"synopsis,omitempty"`
	SynopsisOutputTokens int64 `json:"synopsisOutputTokens,omitempty"`
	// Pipeline is the shape the run came out of, Cohorts how many calls the
	// fan-out made and CohortsFailed how many did not answer, and FellBack
	// the reason a staged run finished as a one-shot review.
	//
	// The shape is recorded because a cost mean across shapes is not a
	// number: a staged row is a call per cohort and a one-shot row is one
	// call, which is the same reason Batched rows are kept out of the
	// distribution. FellBack is what stops a run that paid for a failed
	// stage one and then reviewed in one call from reading as a cheap
	// staged run.
	Pipeline      string `json:"pipeline,omitempty"`
	Cohorts       int    `json:"cohorts,omitempty"`
	CohortsFailed int    `json:"cohortsFailed,omitempty"`
	FellBack      string `json:"fellBack,omitempty"`
	// Ceiling and InputEstimate record what the request was allowed and what
	// it used, so a run that was trimmed can be told from one that fit.
	Ceiling       int  `json:"ceiling"`
	InputEstimate int  `json:"inputEstimate"`
	OverCeiling   bool `json:"overCeiling,omitempty"`
	// Samples is how many independent reviews this line paid for, and
	// SamplesFailed how many of them did not answer. A mean cost across
	// lines is only comparable when it says so: three samples cost three
	// reviews and record as one line.
	Samples       int `json:"samples,omitempty"`
	SamplesFailed int `json:"samplesFailed,omitempty"`
	// RulingOutputTokens is what the verifying pass wrote, and ScoutCostUSD
	// what stage two's lookups cost. Kept apart from Usage and named on their
	// own so a run that checked its findings can be told from one that did
	// not, and so the review's own output median is not inflated by the
	// ruling's handful of objects.
	RulingOutputTokens int64   `json:"rulingOutputTokens,omitempty"`
	ScoutCostUSD       float64 `json:"scoutCostUSD,omitempty"`
}

// Record appends one review to the ledger in dir. Failing to write it is not
// fatal: a review that produced findings has done its job, and losing a cost
// line is not worth failing the command over. The error is returned so the
// caller can say so.
func Record(dir string, r *Result, effort string) error {
	if r == nil {
		return nil
	}
	e := Entry{
		At: time.Now().UTC(), API: r.API, Model: r.Model, Effort: effort,
		Usage: r.Usage, CostUSD: r.CostUSD, Known: r.CostKnown,
		Seconds: r.Duration.Seconds(), Findings: len(r.Review.Comments),
		StopReason: r.StopReason, Truncated: r.Truncated,
		Batched: r.Batched, Cached: r.Cached,
		Synopsis: r.Synopsis, SynopsisOutputTokens: r.SynopsisOutputTokens,
		Pipeline: r.Pipeline, Cohorts: len(r.Cohorts),
		CohortsFailed: r.CohortsFailed, FellBack: r.FellBack,
		Ceiling: r.Ceiling, InputEstimate: r.InputEstimate, OverCeiling: r.OverCeiling,
		Samples: r.Samples, SamplesFailed: r.SamplesFailed,
		RulingOutputTokens: r.RulingOutputTokens, ScoutCostUSD: r.ScoutCostUSD,
	}
	buf, err := json.Marshal(e)
	if err != nil {
		return err
	}
	if err := os.MkdirAll(dir, 0o755); err != nil {
		return err
	}
	// 0600: the ledger records what this developer's reviews cost, which is
	// nobody else's business on a shared machine.
	f, err := os.OpenFile(filepath.Join(dir, ledgerFile), os.O_APPEND|os.O_CREATE|os.O_WRONLY, 0o600)
	if err != nil {
		return err
	}
	defer func() { _ = f.Close() }()
	_, err = f.Write(append(buf, '\n'))
	return err
}

// ReadLedger loads every recorded review from dir. A missing file is not an
// error: no reviews have run yet.
func ReadLedger(dir string) ([]Entry, error) {
	buf, err := os.ReadFile(filepath.Join(dir, ledgerFile))
	if os.IsNotExist(err) {
		return nil, nil
	}
	if err != nil {
		return nil, err
	}
	var out []Entry
	dec := json.NewDecoder(bytes.NewReader(buf))
	for dec.More() {
		var e Entry
		if err := dec.Decode(&e); err != nil {
			return out, fmt.Errorf("%s: %w", ledgerFile, err)
		}
		out = append(out, e)
	}
	return out, nil
}

// Stats is the distribution the target is a claim about.
type Stats struct {
	// Shape is which pipeline these rows came out of, set by
	// SummarizeByShape. Empty when a caller summarised a set it had already
	// chosen.
	Shape  string
	Count  int
	Mean   float64
	Median float64
	P90    float64
	Max    float64
	Min    float64
	// Unknown counts reviews whose model had no rate. They are excluded from
	// every number above, and named, because folding them in as zero would
	// drag the average down with reviews nobody priced.
	Unknown int
	// MeanSeconds is wall time, the other number a pre-push tool is judged on.
	MeanSeconds float64
	// Batched counts rows excluded for having gone over the batch tier.
	Batched int
	// Truncated counts reviews the output cap cut off. They are paid for in
	// full and yield nothing, so they belong beside the average rather than
	// inside it: a rising count is the signal to raise --max-tokens, and it
	// is the one thing that separates a cheap run from a wasted one.
	Truncated int
	// MedianOutput is what reviews actually emitted. It replaces the guess
	// in ExpectedOutputTokens once there is enough evidence to have a
	// median, so the estimate converges on this installation's own reviews
	// rather than staying at a constant somebody picked.
	MedianOutput int64
}

// minForMedianOutput is how many recorded reviews it takes before the measured
// median is trusted over the default. Three is enough to stop one unusually
// long review from setting the estimate for every later one.
const minForMedianOutput = 3

// ExpectedOutput returns the output size to price the next review at: the
// measured median when there is one, and the documented default before that.
func (s Stats) ExpectedOutput() int64 {
	if s.Count >= minForMedianOutput && s.MedianOutput > 0 {
		return s.MedianOutput
	}
	return ExpectedOutputTokens
}

// Shape is the ledger's grouping key: the pipeline a row came out of, with
// the rows written before the field existed reading as what they were.
func (e Entry) Shape() string {
	if e.Pipeline == "" {
		return PipelineOneShot
	}
	return e.Pipeline
}

// SummarizeByShape splits the ledger before averaging it.
//
// A mean across shapes is not a number. A staged row is a describing call
// plus one per cohort and a one-shot row is one call, so a ledger holding
// both reports a cost nobody was ever charged - the same reason Batched rows
// are left out of the distribution below. MedianOutput is worse than
// meaningless mixed: it prices the next review's judging call, and a staged
// row's output is five calls' worth.
func SummarizeByShape(entries []Entry) map[string]Stats {
	byShape := map[string][]Entry{}
	for _, e := range entries {
		byShape[e.Shape()] = append(byShape[e.Shape()], e)
	}
	out := make(map[string]Stats, len(byShape))
	for shape, rows := range byShape {
		s := Summarize(rows)
		s.Shape = shape
		out[shape] = s
	}
	return out
}

// Summarize computes the distribution of whatever it is given. Callers that
// hold a mixed ledger want SummarizeByShape.
func Summarize(entries []Entry) Stats {
	var s Stats
	var costs []float64
	var outs []int64
	var secs float64
	for _, e := range entries {
		if e.Batched {
			s.Batched++
			continue
		}
		if !e.Known {
			s.Unknown++
			continue
		}
		costs = append(costs, e.CostUSD)
		secs += e.Seconds
		if e.Truncated {
			s.Truncated++
		}
		if e.Usage.OutputTokens > 0 {
			outs = append(outs, e.Usage.OutputTokens)
		}
	}
	if len(outs) > 0 {
		sort.Slice(outs, func(i, j int) bool { return outs[i] < outs[j] })
		s.MedianOutput = outs[len(outs)/2]
	}
	s.Count = len(costs)
	if s.Count == 0 {
		return s
	}
	sort.Float64s(costs)
	var sum float64
	for _, c := range costs {
		sum += c
	}
	s.Mean = sum / float64(s.Count)
	s.Median = percentile(costs, 50)
	s.P90 = percentile(costs, 90)
	s.Min = costs[0]
	s.Max = costs[s.Count-1]
	s.MeanSeconds = secs / float64(s.Count)
	return s
}

// percentile is the nearest-rank value at pct of a sorted slice: index
// ceil(pct*n/100)-1.
//
// The naive (n*pct)/100 is one rank too high, and biased the same way at
// every size: at two reviews the "median" was the more expensive of the two,
// and for any n up to ten the "p90" was the maximum, so the tail statistic
// that exists to show one outlier beside the average was that outlier. The
// clamp is for pct at the ends, not for the arithmetic; ceil(pct*n/100)-1 is
// within range for every n >= 1.
func percentile(sorted []float64, pct int) float64 {
	idx := (len(sorted)*pct+99)/100 - 1
	if idx < 0 {
		idx = 0
	}
	if idx >= len(sorted) {
		idx = len(sorted) - 1
	}
	return sorted[idx]
}

// String renders the distribution for a terminal. The average leads because
// that is the number the target is about; the tail is beside it because an
// average alone hides a review that cost ten times the rest.
func (s Stats) String() string {
	if s.Count == 0 {
		if s.Unknown > 0 {
			return fmt.Sprintf("%d review(s) recorded, none with a known rate", s.Unknown)
		}
		return "no reviews recorded yet"
	}
	out := fmt.Sprintf("%d review(s): mean $%.4f, median $%.4f, p90 $%.4f, range $%.4f to $%.4f, mean wall %.1fs",
		s.Count, s.Mean, s.Median, s.P90, s.Min, s.Max, s.MeanSeconds)
	if s.Shape != "" {
		out = s.Shape + ": " + out
	}
	if s.Batched > 0 {
		out += fmt.Sprintf(" (%d more ran at the batch tier's half rate and are excluded)", s.Batched)
	}
	if s.Truncated > 0 {
		out += fmt.Sprintf("; %d hit the output cap and were paid for in full for nothing", s.Truncated)
	}
	if s.Unknown > 0 {
		out += fmt.Sprintf(" (%d more had no rate and are excluded)", s.Unknown)
	}
	return out
}

package review

import (
	"bytes"
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net/http"
	"strings"
	"time"
)

// The OpenAI backend speaks the chat completions protocol over plain HTTP.
//
// It exists for the proxy case. A team that routes every model call through
// one gateway, for billing, audit, or because the vendor's API is not
// reachable from where the review runs, exposes that gateway as an
// OpenAI-compatible endpoint whatever sits behind it. So this is written to
// the protocol rather than to the vendor, with no SDK: the request is one
// JSON body, the response is one JSON body, and the parts a review needs from
// each are small enough to read by hand. Nothing here decides what the review
// sees; that is settled by Assemble before the wire is chosen.

// DefaultOpenAIModel is the model used when --api openai names none.
// A proxy may alias this to anything; the ledger records what was asked for.
const DefaultOpenAIModel = "gpt-5"

// defaultOpenAIBaseURL is the vendor's own endpoint, used when no BaseURL
// is given. A proxy replaces it.
const defaultOpenAIBaseURL = "https://api.openai.com/v1"

// openAIHTTPClient is swapped by tests. The default bounds a request at ten
// minutes. A review runs two to five, so this leaves margin, while a proxy
// that accepts the connection and then stalls fails the command instead of
// hanging it forever, which http.DefaultClient with no timeout allowed.
var openAIHTTPClient = &http.Client{Timeout: 10 * time.Minute}

type openAIMessage struct {
	Role    string `json:"role"`
	Content string `json:"content"`
}

type openAIRequest struct {
	Model    string          `json:"model"`
	Messages []openAIMessage `json:"messages"`
	// MaxCompletionTokens is the current name for the output cap; the older
	// max_tokens is rejected by reasoning models.
	MaxCompletionTokens int64 `json:"max_completion_tokens"`
	// Tools carries the schema as a single function, and ToolChoice forces the
	// model to call it. This is asked for instead of response_format because a
	// gateway that serves one vendor's model over another's protocol does not
	// enforce response_format: on this repository's own Marketplace gateway
	// one review in four came back with the schema's array as a JSON string or
	// an object, and the checking pass failed open on the parse. Function
	// calling is honoured where the schema is not, because the same gateway
	// drives the scout's tool loop reliably.
	Tools           []openAITool `json:"tools,omitempty"`
	ToolChoice      any          `json:"tool_choice,omitempty"`
	ReasoningEffort string       `json:"reasoning_effort,omitempty"`
}

type openAITool struct {
	Type     string         `json:"type"`
	Function openAIFunction `json:"function"`
}

type openAIFunction struct {
	Name        string `json:"name"`
	Description string `json:"description,omitempty"`
	Parameters  any    `json:"parameters"`
}

// openAIResponse is the non-streamed reply. Only the fields a review reads are
// named; a proxy may add more and they are ignored. The structured body is the
// forced tool call's arguments; content is read only when a proxy ignored the
// tool call and answered in prose instead.
type openAIResponse struct {
	Choices []struct {
		Message struct {
			Content   string `json:"content"`
			Refusal   string `json:"refusal"`
			ToolCalls []struct {
				Function struct {
					Name      string `json:"name"`
					Arguments string `json:"arguments"`
				} `json:"function"`
			} `json:"tool_calls"`
		} `json:"message"`
		FinishReason string `json:"finish_reason"`
	} `json:"choices"`
	Usage *struct {
		PromptTokens        int64 `json:"prompt_tokens"`
		CompletionTokens    int64 `json:"completion_tokens"`
		PromptTokensDetails struct {
			CachedTokens int64 `json:"cached_tokens"`
		} `json:"prompt_tokens_details"`
	} `json:"usage"`
	Error *openAIError `json:"error"`
}

type openAIError struct {
	Message string `json:"message"`
	Type    string `json:"type"`
}

// completeOpenAI sends the assembled request as one forced tool call and reads
// the reply. Non-streaming for the same reason the scout is: a tool call is
// read off a finished turn, and streaming its arguments back would buy nothing
// but reassembly.
func completeOpenAI(ctx context.Context, opts Options, res *Result) (completion, error) {
	base := strings.TrimRight(opts.BaseURL, "/")
	if base == "" {
		base = defaultOpenAIBaseURL
	}
	if opts.APIKey == "" && base == defaultOpenAIBaseURL {
		// A proxy may need no key. The vendor's own endpoint always does,
		// and a 401 after the whole prompt has been uploaded is a worse way
		// to find out.
		return completion{}, errors.New("OPENAI_API_KEY is not set")
	}

	// Every stage's function goes out on every call and the stage is chosen by
	// name, which is what the Anthropic wire now does too. Here it buys
	// nothing directly: a gateway's cache is its own business and this
	// protocol says nothing about one. It is done anyway so that a request is
	// the same request over either wire, which is the property that lets the
	// eval compare an arm run over one against an arm run over the other.
	fn := res.stage()
	body := openAIRequest{
		Model: opts.Model,
		Messages: []openAIMessage{
			{Role: "system", Content: res.System},
			// One string, because this protocol's user turn is one string and
			// there is no breakpoint here to keep the two apart for.
			{Role: "user", Content: res.Prompt + res.Tail},
		},
		MaxCompletionTokens: opts.MaxTokens,
		Tools:               openAITools(opts),
		ToolChoice: map[string]any{
			"type":     "function",
			"function": map[string]any{"name": fn},
		},
		ReasoningEffort: opts.Effort,
	}
	buf, err := json.Marshal(body)
	if err != nil {
		return completion{}, err
	}
	req, err := http.NewRequestWithContext(ctx, http.MethodPost, base+"/chat/completions", bytes.NewReader(buf))
	if err != nil {
		return completion{}, err
	}
	req.Header.Set("Content-Type", "application/json")
	req.Header.Set("Accept", "application/json")
	if token := bearerToken(opts); token != "" {
		req.Header.Set("Authorization", "Bearer "+token)
	}

	resp, err := openAIHTTPClient.Do(req)
	if err != nil {
		return completion{}, err
	}
	defer func() { _ = resp.Body.Close() }()
	if resp.StatusCode != http.StatusOK {
		return completion{}, openAIStatusError(resp)
	}
	raw, err := io.ReadAll(io.LimitReader(resp.Body, 8<<20))
	if err != nil {
		return completion{}, err
	}
	return readOpenAIResponse(raw)
}

// bearerToken is what follows "Bearer" in the Authorization header. A
// gateway that meters by caller wants the user in the token beside the key,
// as user=<user>&key=<key>; with no user named, the key goes as it is.
func bearerToken(opts Options) string {
	if opts.APIUser == "" {
		return opts.APIKey
	}
	return "user=" + opts.APIUser + "&key=" + opts.APIKey
}

// openAIStatusError turns a non-200 into an error that quotes the server's
// own message when it sent one, since that is where a proxy says what it
// did not like about the request.
func openAIStatusError(resp *http.Response) error {
	raw, _ := io.ReadAll(io.LimitReader(resp.Body, 64<<10))
	var e struct {
		Error *openAIError `json:"error"`
	}
	if json.Unmarshal(raw, &e) == nil && e.Error != nil && e.Error.Message != "" {
		return fmt.Errorf("%s: %s", resp.Status, e.Error.Message)
	}
	if msg := strings.TrimSpace(string(raw)); msg != "" {
		return fmt.Errorf("%s: %s", resp.Status, msg)
	}
	return errors.New(resp.Status)
}

// readOpenAIResponse turns the reply into a completion. The structured body is
// the forced tool call's arguments; a gateway that ignored tool_choice and
// answered in content is still read, fenced or not, so a dropped constraint
// degrades to prose in the body rather than an empty review.
func readOpenAIResponse(raw []byte) (completion, error) {
	var r openAIResponse
	if err := json.Unmarshal(raw, &r); err != nil {
		return completion{}, fmt.Errorf("unreadable response: %w", err)
	}
	if r.Error != nil && strings.TrimSpace(r.Error.Message) != "" {
		return completion{}, fmt.Errorf("response error: %s", r.Error.Message)
	}
	var c completion
	if r.Usage != nil {
		// The vendor counts cached tokens inside prompt_tokens; Usage keeps
		// them apart so they price at the cached rate.
		cached := r.Usage.PromptTokensDetails.CachedTokens
		c.usage = Usage{
			InputTokens:     r.Usage.PromptTokens - cached,
			OutputTokens:    r.Usage.CompletionTokens,
			CacheReadTokens: cached,
		}
	}
	if len(r.Choices) == 0 {
		return c, errors.New("the response carried no choices")
	}
	ch := r.Choices[0]
	c.stopReason = ch.FinishReason
	for _, tc := range ch.Message.ToolCalls {
		if strings.TrimSpace(tc.Function.Arguments) != "" {
			c.text = tc.Function.Arguments
			break
		}
	}
	if c.text == "" {
		c.text = stripFences(ch.Message.Content)
	}
	switch {
	case strings.TrimSpace(ch.Message.Refusal) != "":
		c.refused = true
		c.detail = strings.TrimSpace(ch.Message.Refusal)
	case ch.FinishReason == "content_filter":
		c.refused = true
		c.detail = "content filter"
	case ch.FinishReason == "length":
		c.truncated = true
	}
	return c, nil
}

// stripFences removes a Markdown code fence around a JSON body. A model held
// to a schema does not add one; a proxy that quietly drops the schema
// constraint sometimes lets one through, and the review inside is still
// worth reading.
func stripFences(s string) string {
	t := strings.TrimSpace(s)
	if !strings.HasPrefix(t, "```") {
		return s
	}
	t = strings.TrimPrefix(t, "```")
	if i := strings.IndexByte(t, '\n'); i >= 0 {
		t = t[i+1:]
	}
	t = strings.TrimSuffix(strings.TrimSpace(t), "```")
	return strings.TrimSpace(t)
}

